-- Origami FarmOS — PostgreSQL schema, rendered from the ORM metadata.
--
-- GENERATED FILE. Do not edit by hand: regenerate it with
--     cd backend && python -m app.export_schema
-- backend/tests/test_generated_artifacts.py fails when this file no longer
-- matches backend/app/domain/*.py.
--
-- How a real database gets this schema is Alembic:
--     cd backend && alembic -c alembic.ini upgrade head
-- (.github/workflows/migrate-seed-db.yml runs exactly that). The Alembic
-- chain is verified against these models table by table, column by column,
-- index by index in backend/tests/test_migrations.py, so this file, the
-- migrations and the ORM describe one schema.
--
-- Use this file to read or review the shape, or to provision a database
-- without running the application:
--     psql "$DATABASE_URL" -f database/schema.sql
--     cd backend && alembic -c alembic.ini stamp head   # so later migrations apply
-- Reference rows (units of measure, species, capability rules, feed and
-- medicine categories, ...) come from the migrations and seeders, not from
-- this file; `python -m app.seed` loads the demo farm,
-- `python -m app.seed_production` the real accounts.
--
-- Identifiers are 36-character strings (UUIDs are generated by the
-- application; demo data uses readable ids), timestamps are
-- TIMESTAMP WITH TIME ZONE holding UTC, and JSON columns are plain JSON —
-- the types the models declare and the migrations create.
-- 122 tables, 28 secondary indexes.

CREATE TABLE capabilities (
    code VARCHAR(40) NOT NULL,
    category VARCHAR(30) NOT NULL,
    label_en VARCHAR(80) NOT NULL,
    label_ar VARCHAR(80) NOT NULL,
    active BOOLEAN NOT NULL,
    PRIMARY KEY (code)
);

CREATE TABLE farms (
    id VARCHAR(36) NOT NULL,
    name VARCHAR(200) NOT NULL,
    country VARCHAR(100) NOT NULL,
    region VARCHAR(100) NOT NULL,
    timezone VARCHAR(50) NOT NULL,
    default_currency VARCHAR(10) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE feed_nutrients (
    code VARCHAR(30) NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    name_ar VARCHAR(100) NOT NULL,
    unit VARCHAR(20) NOT NULL,
    category VARCHAR(30) NOT NULL,
    sort_order INTEGER NOT NULL,
    PRIMARY KEY (code)
);

CREATE TABLE idempotency_records (
    id VARCHAR(36) NOT NULL,
    idempotency_key VARCHAR(100) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    method VARCHAR(10) NOT NULL,
    path VARCHAR(300) NOT NULL,
    status_code INTEGER NOT NULL,
    response_body TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_idempotency_key_user UNIQUE (idempotency_key, user_id)
);
CREATE INDEX ix_idempotency_records_key ON idempotency_records (idempotency_key);

CREATE TABLE medicine_active_ingredients (
    id VARCHAR(36) NOT NULL,
    code VARCHAR(80) NOT NULL,
    name VARCHAR(180) NOT NULL,
    active BOOLEAN NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (code)
);

CREATE TABLE medicine_categories (
    id VARCHAR(36) NOT NULL,
    code VARCHAR(80) NOT NULL,
    name VARCHAR(150) NOT NULL,
    name_ar VARCHAR(150),
    active BOOLEAN NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (code)
);

CREATE TABLE species (
    code VARCHAR(30) NOT NULL,
    name_en VARCHAR(80) NOT NULL,
    name_ar VARCHAR(80) NOT NULL,
    reproduction_mode VARCHAR(20) NOT NULL,
    icon VARCHAR(30) NOT NULL,
    default_management VARCHAR(20) NOT NULL,
    terminology_json JSON NOT NULL,
    profiles_json JSON,
    active BOOLEAN NOT NULL,
    sort_order INTEGER NOT NULL,
    PRIMARY KEY (code)
);

CREATE TABLE sync_queue (
    id VARCHAR(36) NOT NULL,
    local_event_id VARCHAR(36),
    operation VARCHAR(20) NOT NULL,
    entity_type VARCHAR(30) NOT NULL,
    entity_id VARCHAR(36) NOT NULL,
    payload_json JSON NOT NULL,
    status VARCHAR(20) NOT NULL,
    retry_count INTEGER NOT NULL,
    last_error VARCHAR(500),
    idempotency_key VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (idempotency_key)
);

CREATE TABLE units_of_measure (
    code VARCHAR(30) NOT NULL,
    name_en VARCHAR(80) NOT NULL,
    name_ar VARCHAR(80),
    dimension VARCHAR(30) NOT NULL,
    base_unit_code VARCHAR(30),
    factor_to_base FLOAT NOT NULL,
    active BOOLEAN NOT NULL,
    sort_order INTEGER NOT NULL,
    PRIMARY KEY (code),
    FOREIGN KEY(base_unit_code) REFERENCES units_of_measure (code)
);

CREATE TABLE audit_log (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    action VARCHAR(100) NOT NULL,
    entity_type VARCHAR(30) NOT NULL,
    entity_id VARCHAR(36) NOT NULL,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    metadata_json JSON NOT NULL,
    module_code VARCHAR(40),
    summary VARCHAR(500),
    changes_json JSON,
    device VARCHAR(120),
    PRIMARY KEY (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id)
);

CREATE TABLE breeds (
    id VARCHAR(36) NOT NULL,
    species_code VARCHAR(30) NOT NULL,
    name VARCHAR(100) NOT NULL,
    name_ar VARCHAR(100),
    active BOOLEAN NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY(species_code) REFERENCES species (code)
);

CREATE TABLE crops (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    name VARCHAR(120) NOT NULL,
    category VARCHAR(60),
    default_cycle_days INTEGER,
    active BOOLEAN NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
