    FOREIGN KEY(farm_id) REFERENCES farms (id)
);

CREATE TABLE animals (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    tag VARCHAR(50),
    name VARCHAR(200) NOT NULL,
    species VARCHAR(30) NOT NULL,
    breed VARCHAR(100),
    breed_id VARCHAR(36),
    sex VARCHAR(5),
    birth_date TIMESTAMP WITH TIME ZONE,
    birth_date_estimated BOOLEAN NOT NULL,
    life_stage VARCHAR(30),
    management_profile VARCHAR(30),
    status VARCHAR(30) NOT NULL,
    location_id VARCHAR(36),
    location_label VARCHAR(200),
    health_score INTEGER NOT NULL,
    pregnant BOOLEAN NOT NULL,
    pregnancy_days INTEGER,
    lactating BOOLEAN NOT NULL,
    lactation_cycle INTEGER,
    withdrawal_until TIMESTAMP WITH TIME ZONE,
    withdrawal_reason VARCHAR(200),
    weight_kg FLOAT,
    lactation_started_at TIMESTAMP WITH TIME ZONE,
    dried_off_at TIMESTAMP WITH TIME ZONE,
    group_name VARCHAR(100),
    photo_path VARCHAR(500),
    acquisition_date TIMESTAMP WITH TIME ZONE,
    acquisition_source VARCHAR(200),
    sire_tag VARCHAR(50),
    dam_tag VARCHAR(50),
    color_markings VARCHAR(200),
    purchase_cost FLOAT,
    current_value FLOAT,
    notes TEXT,
    active BOOLEAN NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
