    planned_cost FLOAT,
    actual_cost FLOAT,
    unit_cost FLOAT,
    output_lot_id VARCHAR(36),
    started_at TIMESTAMP WITH TIME ZONE NOT NULL,
    produced_at TIMESTAMP WITH TIME ZONE,
    mixed_by VARCHAR(36),
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_feed_batch_farm_code UNIQUE (farm_id, batch_code),
    CONSTRAINT uq_feed_batch_farm_mix_number UNIQUE (farm_id, mix_number),
    CONSTRAINT uq_feed_batch_farm_mix_code UNIQUE (farm_id, mix_code),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(formula_version_id) REFERENCES feed_formula_versions (id),
    FOREIGN KEY(intended_species_code) REFERENCES species (code),
    FOREIGN KEY(intended_management_profile) REFERENCES management_profiles (code),
    FOREIGN KEY(operator_id) REFERENCES users (id),
    FOREIGN KEY(mixer_asset_id) REFERENCES farm_assets (id)
);

CREATE TABLE feed_formula_components (
    id VARCHAR(36) NOT NULL,
    version_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    target_quantity FLOAT NOT NULL,
    unit VARCHAR(20) NOT NULL,
    target_percentage FLOAT,
    sort_order INTEGER NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY(version_id) REFERENCES feed_formula_versions (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id)
);

CREATE TABLE medication_administrations (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    subject_type VARCHAR(10) NOT NULL,
    subject_id VARCHAR(36) NOT NULL,
    treatment_id VARCHAR(36),
    protocol_run_step_id VARCHAR(36),
    inventory_item_id VARCHAR(36) NOT NULL,
    inventory_lot_id VARCHAR(36) NOT NULL,
    reservation_id VARCHAR(36),
    location_id VARCHAR(36),
    dose_quantity FLOAT NOT NULL,
    dose_unit VARCHAR(30) NOT NULL,
    route_code VARCHAR(40) NOT NULL,
    head_count INTEGER NOT NULL,
    quantity_consumed FLOAT NOT NULL,
    unit VARCHAR(30) NOT NULL,
    administered_at TIMESTAMP WITH TIME ZONE NOT NULL,
    administered_by VARCHAR(36) NOT NULL,
    inventory_transaction_id VARCHAR(36),
    withdrawal_milk_until TIMESTAMP WITH TIME ZONE,
    withdrawal_meat_until TIMESTAMP WITH TIME ZONE,
    reason TEXT,
    notes TEXT,
    status VARCHAR(20) NOT NULL,
    reversed_at TIMESTAMP WITH TIME ZONE,
    reversal_reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(treatment_id) REFERENCES treatments (id),
    FOREIGN KEY(inventory_item_id) REFERENCES medicine_products (inventory_item_id),
    FOREIGN KEY(inventory_lot_id) REFERENCES inventory_lots (id),
    FOREIGN KEY(reservation_id) REFERENCES inventory_reservations (id),
    FOREIGN KEY(location_id) REFERENCES locations (id),
    FOREIGN KEY(dose_unit) REFERENCES units_of_measure (code),
    FOREIGN KEY(unit) REFERENCES units_of_measure (code)
);
CREATE INDEX ix_medication_admin_subject ON medication_administrations (farm_id, subject_type, subject_id);

CREATE TABLE feed_batch_performance_scores (
    feed_batch_id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    evaluated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    exposed_head_count INTEGER,
    exposure_days FLOAT,
    formula_compliance_score FLOAT,
    intake_response_score FLOAT,
    production_response_score FLOAT,
    health_signal_score FLOAT,
    consistency_score FLOAT,
    economic_score FLOAT,
    overall_score FLOAT,
    confidence_score FLOAT NOT NULL,
    evidence_json JSON NOT NULL,
    PRIMARY KEY (feed_batch_id),
    FOREIGN KEY(feed_batch_id) REFERENCES feed_batches (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id)
);

CREATE TABLE feed_lots (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    lot_code VARCHAR(80) NOT NULL,
    source_type VARCHAR(20) NOT NULL,
    supplier_id VARCHAR(36),
    supplier_label VARCHAR(200),
    feed_batch_id VARCHAR(36),
    received_at TIMESTAMP WITH TIME ZONE NOT NULL,
    expiry_date TIMESTAMP WITH TIME ZONE,
    ordered_quantity FLOAT,
    received_quantity FLOAT NOT NULL,
    accepted_quantity FLOAT NOT NULL,
    rejected_quantity FLOAT NOT NULL,
    quantity_on_hand FLOAT NOT NULL,
    unit VARCHAR(20) NOT NULL,
    unit_cost FLOAT,
    status VARCHAR(20) NOT NULL,
    reference VARCHAR(120),
    notes TEXT,
    created_by VARCHAR(36),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_feed_lot_farm_code UNIQUE (farm_id, lot_code),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(supplier_id) REFERENCES suppliers (id),
    FOREIGN KEY(feed_batch_id) REFERENCES feed_batches (id)
);

CREATE TABLE feed_performance_alerts (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    assessment_id VARCHAR(36),
    feed_batch_id VARCHAR(36),
    feed_product_id VARCHAR(36),
    subject_type VARCHAR(10),
    subject_id VARCHAR(36),
    alert_type VARCHAR(60) NOT NULL,
    severity VARCHAR(20) NOT NULL,
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL,
    title VARCHAR(200) NOT NULL,
    explanation TEXT NOT NULL,
    evidence_json JSON NOT NULL,
    confidence_score FLOAT,
    status VARCHAR(30) NOT NULL,
    deduplication_key VARCHAR(255) NOT NULL,
    acknowledged_by VARCHAR(36),
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    resolution_note TEXT,
    PRIMARY KEY (id),
    CONSTRAINT uq_feed_perf_alert_dedup UNIQUE (farm_id, deduplication_key, detected_at),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(assessment_id) REFERENCES feed_performance_assessments (id),
    FOREIGN KEY(feed_batch_id) REFERENCES feed_batches (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id)
);
CREATE INDEX ix_feed_perf_alert_status ON feed_performance_alerts (farm_id, status);

CREATE TABLE protocol_run_steps (
    id VARCHAR(36) NOT NULL,
    protocol_run_id VARCHAR(36) NOT NULL,
    protocol_step_id VARCHAR(36) NOT NULL,
    sequence INTEGER NOT NULL,
    status VARCHAR(30) NOT NULL,
    due_at TIMESTAMP WITH TIME ZONE,
    presented_at TIMESTAMP WITH TIME ZONE,
    confirmed_at TIMESTAMP WITH TIME ZONE,
    confirmed_by VARCHAR(36),
    completed_at TIMESTAMP WITH TIME ZONE,
    medication_administration_id VARCHAR(36),
    result_payload JSON NOT NULL,
    skip_reason TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY(protocol_run_id) REFERENCES emergency_protocol_runs (id),
    FOREIGN KEY(protocol_step_id) REFERENCES protocol_steps (id),
    FOREIGN KEY(medication_administration_id) REFERENCES medication_administrations (id)
);

CREATE TABLE feed_allocations (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    lot_id VARCHAR(36),
    species_code VARCHAR(30),
    subject_type VARCHAR(10),
    subject_id VARCHAR(36),
    feeding_program_id VARCHAR(36),
    location_label VARCHAR(200),
    cost_centre VARCHAR(100),
    purpose VARCHAR(300),
    allocated_quantity FLOAT NOT NULL,
    consumed_quantity FLOAT NOT NULL,
    unit VARCHAR(20) NOT NULL,
    transferable BOOLEAN NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_by VARCHAR(36),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    released_at TIMESTAMP WITH TIME ZONE,
    PRIMARY KEY (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id),
    FOREIGN KEY(species_code) REFERENCES species (code),
    FOREIGN KEY(feeding_program_id) REFERENCES feeding_programs (id)
);

CREATE TABLE feed_batch_components (
    id VARCHAR(36) NOT NULL,
    batch_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    lot_id VARCHAR(36),
    target_quantity FLOAT,
    actual_quantity FLOAT,
    unit VARCHAR(20) NOT NULL,
    unit_cost FLOAT,
    cost FLOAT,
    PRIMARY KEY (id),
    FOREIGN KEY(batch_id) REFERENCES feed_batches (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id)
);

CREATE TABLE feed_exposure_windows (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    subject_type VARCHAR(10) NOT NULL,
    subject_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    lot_id VARCHAR(36),
    feed_batch_id VARCHAR(36),
    exposure_start TIMESTAMP WITH TIME ZONE NOT NULL,
    exposure_end TIMESTAMP WITH TIME ZONE,
    offered_quantity FLOAT NOT NULL,
    consumed_estimate FLOAT,
    feeding_event_count INTEGER NOT NULL,
    lineage_json JSON NOT NULL,
    generated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id),
    FOREIGN KEY(feed_batch_id) REFERENCES feed_batches (id)
);
CREATE INDEX ix_feed_exposure_batch ON feed_exposure_windows (feed_batch_id);
CREATE INDEX ix_feed_exposure_subject ON feed_exposure_windows (farm_id, subject_type, subject_id);

CREATE TABLE feed_reconciliations (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    lot_id VARCHAR(36),
    period_from TIMESTAMP WITH TIME ZONE NOT NULL,
    period_to TIMESTAMP WITH TIME ZONE NOT NULL,
    opening_quantity FLOAT NOT NULL,
    received_quantity FLOAT NOT NULL,
    issued_to_batches FLOAT NOT NULL,
    issued_to_feeding FLOAT NOT NULL,
    other_issued_quantity FLOAT NOT NULL,
    waste_quantity FLOAT NOT NULL,
    returned_quantity FLOAT NOT NULL,
    adjustment_quantity FLOAT NOT NULL,
    expected_closing_quantity FLOAT NOT NULL,
    counted_closing_quantity FLOAT,
    variance_quantity FLOAT,
    variance_pct FLOAT,
    unit VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL,
    explanation TEXT,
    created_by VARCHAR(36),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    closed_at TIMESTAMP WITH TIME ZONE,
    PRIMARY KEY (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id)
);

CREATE TABLE feed_usage_policies (
    id VARCHAR(36) NOT NULL,
    farm_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36),
    lot_id VARCHAR(36),
    name VARCHAR(200) NOT NULL,
    requires_approved_formula BOOLEAN NOT NULL,
    cross_species_transfer_allowed BOOLEAN NOT NULL,
    status VARCHAR(20) NOT NULL,
    effective_from TIMESTAMP WITH TIME ZONE,
    effective_to TIMESTAMP WITH TIME ZONE,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY(farm_id) REFERENCES farms (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id)
);

CREATE TABLE feeding_event_components (
    id VARCHAR(36) NOT NULL,
    event_id VARCHAR(36) NOT NULL,
    feed_product_id VARCHAR(36) NOT NULL,
    lot_id VARCHAR(36),
    batch_id VARCHAR(36),
    quantity_offered FLOAT NOT NULL,
    quantity_consumed FLOAT,
    unit VARCHAR(20) NOT NULL,
    unit_cost FLOAT,
    cost FLOAT,
    PRIMARY KEY (id),
    FOREIGN KEY(event_id) REFERENCES feeding_events (id),
    FOREIGN KEY(feed_product_id) REFERENCES feed_products (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id),
    FOREIGN KEY(batch_id) REFERENCES feed_batches (id)
);

CREATE TABLE inventory_transactions (
    id VARCHAR(36) NOT NULL,
    item_id VARCHAR(36) NOT NULL,
    direction VARCHAR(10) NOT NULL,
    quantity FLOAT NOT NULL,
    unit_cost FLOAT,
    reason VARCHAR(100),
    linked_entity_type VARCHAR(50),
    linked_entity_id VARCHAR(36),
    lot_id VARCHAR(36),
    inventory_lot_id VARCHAR(36),
    location_id VARCHAR(36),
    correlation_id VARCHAR(36),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY(item_id) REFERENCES inventory_items (id),
    FOREIGN KEY(lot_id) REFERENCES feed_lots (id),
    FOREIGN KEY(inventory_lot_id) REFERENCES inventory_lots (id),
    FOREIGN KEY(location_id) REFERENCES locations (id)
);

CREATE TABLE feed_usage_policy_rules (
    id VARCHAR(36) NOT NULL,
    policy_id VARCHAR(36) NOT NULL,
    effect VARCHAR(10) NOT NULL,
    species_code VARCHAR(30),
    management_profile VARCHAR(30),
    life_stage VARCHAR(30),
    reproductive_state VARCHAR(20),
    max_inclusion_pct FLOAT,
    min_age_days INTEGER,
    max_age_days INTEGER,
    reason VARCHAR(300),
    PRIMARY KEY (id),
    FOREIGN KEY(policy_id) REFERENCES feed_usage_policies (id),
    FOREIGN KEY(species_code) REFERENCES species (code)
);
